const { Op }=require('sequelize');
const db=require('../../models');
const AppError=require('../../utils/AppError');
const own=(o,k)=>Object.prototype.hasOwnProperty.call(o,k), nil=v=>v==null?null:(typeof v==='string'?(v.trim()||null):v);
const code=v=>String(v||'').trim().toUpperCase().replace(/[^A-Z0-9]+/g,'_').replace(/^_+|_+$/g,'');
const itemInc=[{model:db.Product,as:'product',required:false},{model:db.ProductVariant,as:'productVariant',required:false},{model:db.ProtectionScheme,as:'protectionScheme',required:false}];
const bundleInc=[{model:db.BundlePromotionItem,as:'items',required:false,separate:true,order:[['sortOrder','ASC']],include:itemInc}];
const configInc=[{model:db.Product,as:'product',required:false},{model:db.ProductVariant,as:'productVariant',required:false},{model:db.BundlePromotion,as:'bundles',required:false,separate:true,order:[['sortOrder','ASC']],include:bundleInc}];
async function get(M,id,companyId,msg,err,t,lock){const o={where:{id,companyId},transaction:t};if(t&&lock)o.lock=t.LOCK.UPDATE;const r=await M.findOne(o);if(!r)throw new AppError(msg,404,err);return r}
async function product(companyId,id,t){const r=await db.Product.findOne({where:{id,companyId},transaction:t});if(!r)throw new AppError('Product not found.',400,'BUNDLE_PRODUCT_INVALID');return r}
async function variant(companyId,pid,id,t){if(!id)return;const r=await db.ProductVariant.findOne({where:{id,productId:pid},include:[{model:db.Product,as:'product',required:true,where:{companyId},attributes:['id']}],transaction:t});if(!r)throw new AppError('Variant does not belong to selected product.',400,'BUNDLE_VARIANT_INVALID')}
async function uniqueConfig(companyId,pid,vid,ch,exclude,t){const w={companyId,productId:pid,channelCode:ch,productVariantId:vid||{[Op.is]:null}};if(exclude)w.id={[Op.ne]:exclude};if(await db.BundlePromotionConfig.findOne({where:w,transaction:t}))throw new AppError('Configuration already exists.',409,'BUNDLE_CONFIG_EXISTS')}
async function uniqueCode(companyId,cid,c,exclude,t){const w={companyId,configId:cid,code:c};if(exclude)w.id={[Op.ne]:exclude};if(await db.BundlePromotion.findOne({where:w,transaction:t}))throw new AppError('Bundle code already exists.',409,'BUNDLE_CODE_EXISTS')}
function pricing(m,a){if(m==='FREE')return null;if(a==null||a==='')throw new AppError(`${m} requires priceAmount.`,400,'BUNDLE_PRICE_REQUIRED');a=Number(a);if(!Number.isFinite(a)||a<0)throw new AppError('Invalid priceAmount.',400,'BUNDLE_PRICE_INVALID');return a}
function dates(a,b){if(a&&b&&new Date(b)<new Date(a))throw new AppError('endsAt cannot be before startsAt.',400,'BUNDLE_DATE_RANGE_INVALID')}
async function getConfigById({companyId,configId}){const r=await db.BundlePromotionConfig.findOne({where:{id:configId,companyId},include:configInc});if(!r)throw new AppError('Configuration not found.',404,'BUNDLE_CONFIG_NOT_FOUND');return r}
async function listConfigs({companyId,page=1,pageSize=30,productId,productVariantId,channelCode,isActive}){const w={companyId};if(productId)w.productId=productId;if(productVariantId)w.productVariantId=productVariantId;if(channelCode)w.channelCode=channelCode;if(typeof isActive==='boolean')w.isActive=isActive;page=+page;pageSize=+pageSize;const r=await db.BundlePromotionConfig.findAndCountAll({where:w,include:configInc.slice(0,2),distinct:true,limit:pageSize,offset:(page-1)*pageSize,order:[['createdAt','DESC']]});return{rows:r.rows,pagination:{page,pageSize,totalItems:r.count,totalPages:Math.ceil(r.count/pageSize)}}}
async function createConfig({companyId,userId,payload}){const t=await db.sequelize.transaction();try{const pid=payload.productId,vid=nil(payload.productVariantId),ch=String(payload.channelCode||'WEBSITE').toUpperCase();await product(companyId,pid,t);await variant(companyId,pid,vid,t);await uniqueConfig(companyId,pid,vid,ch,null,t);const r=await db.BundlePromotionConfig.create({companyId,productId:pid,productVariantId:vid,bundlesOptional:payload.bundlesOptional!==false,maxBundleSelectionsPerUnit:Number(payload.maxBundleSelectionsPerUnit||1),maxBundlesDisplayed:payload.maxBundlesDisplayed==null?null:Number(payload.maxBundlesDisplayed),channelCode:ch,isActive:payload.isActive!==false,createdBy:userId,updatedBy:userId},{transaction:t});await t.commit();return getConfigById({companyId,configId:r.id})}catch(e){if(!t.finished)await t.rollback();throw e}}
async function updateConfig({companyId,configId,userId,payload}){const t=await db.sequelize.transaction();try{const r=await get(db.BundlePromotionConfig,configId,companyId,'Configuration not found.','BUNDLE_CONFIG_NOT_FOUND',t,true),pid=own(payload,'productId')?payload.productId:r.productId,vid=own(payload,'productVariantId')?nil(payload.productVariantId):r.productVariantId,ch=own(payload,'channelCode')?String(payload.channelCode).toUpperCase():r.channelCode;await product(companyId,pid,t);await variant(companyId,pid,vid,t);await uniqueConfig(companyId,pid,vid,ch,r.id,t);const v={productId:pid,productVariantId:vid,channelCode:ch,updatedBy:userId};['bundlesOptional','isActive'].forEach(f=>{if(own(payload,f))v[f]=payload[f]});if(own(payload,'maxBundleSelectionsPerUnit'))v.maxBundleSelectionsPerUnit=+payload.maxBundleSelectionsPerUnit;if(own(payload,'maxBundlesDisplayed'))v.maxBundlesDisplayed=payload.maxBundlesDisplayed==null?null:+payload.maxBundlesDisplayed;await r.update(v,{transaction:t});await t.commit();return getConfigById({companyId,configId})}catch(e){if(!t.finished)await t.rollback();throw e}}
async function changeConfigStatus({companyId,configId,userId,isActive}){const r=await get(db.BundlePromotionConfig,configId,companyId,'Configuration not found.','BUNDLE_CONFIG_NOT_FOUND');await r.update({isActive,updatedBy:userId});return getConfigById({companyId,configId})}
async function deleteConfig({companyId,configId}){const t=await db.sequelize.transaction();try{const r=await get(db.BundlePromotionConfig,configId,companyId,'Configuration not found.','BUNDLE_CONFIG_NOT_FOUND',t,true),bs=await db.BundlePromotion.findAll({where:{companyId,configId},attributes:['id'],transaction:t}),ids=bs.map(x=>x.id);if(ids.length)await db.BundlePromotionItem.destroy({where:{companyId,bundlePromotionId:{[Op.in]:ids}},transaction:t});await db.BundlePromotion.destroy({where:{companyId,configId},transaction:t});await r.destroy({transaction:t});await t.commit();return{id:configId}}catch(e){if(!t.finished)await t.rollback();throw e}}
async function getBundleById({companyId,bundleId}){const r=await db.BundlePromotion.findOne({where:{id:bundleId,companyId},include:bundleInc});if(!r)throw new AppError('Bundle not found.',404,'BUNDLE_PROMOTION_NOT_FOUND');return r}
async function listBundles({companyId,configId}){await get(db.BundlePromotionConfig,configId,companyId,'Configuration not found.','BUNDLE_CONFIG_NOT_FOUND');return db.BundlePromotion.findAll({where:{companyId,configId},include:bundleInc,order:[['sortOrder','ASC']]})}
async function createBundle({companyId,configId,userId,payload}){const t=await db.sequelize.transaction();try{await get(db.BundlePromotionConfig,configId,companyId,'Configuration not found.','BUNDLE_CONFIG_NOT_FOUND',t,true);const c=code(payload.code),m=String(payload.priceMode||'FREE').toUpperCase(),p=pricing(m,payload.priceAmount),a=nil(payload.startsAt),b=nil(payload.endsAt);await uniqueCode(companyId,configId,c,null,t);dates(a,b);if(payload.isDefault===true)await db.BundlePromotion.update({isDefault:false},{where:{companyId,configId},transaction:t});const r=await db.BundlePromotion.create({companyId,configId,code:c,name:String(payload.name).trim(),description:nil(payload.description),priceMode:m,priceAmount:p,currencyCode:String(payload.currencyCode||'AED').toUpperCase(),startsAt:a,endsAt:b,badgeText:nil(payload.badgeText),isDefault:payload.isDefault===true,sortOrder:+(payload.sortOrder||0),isActive:payload.isActive!==false,createdBy:userId,updatedBy:userId},{transaction:t});await t.commit();return getBundleById({companyId,bundleId:r.id})}catch(e){if(!t.finished)await t.rollback();throw e}}
async function updateBundle({companyId,bundleId,userId,payload}){const t=await db.sequelize.transaction();try{const r=await get(db.BundlePromotion,bundleId,companyId,'Bundle not found.','BUNDLE_PROMOTION_NOT_FOUND',t,true),c=own(payload,'code')?code(payload.code):r.code,m=own(payload,'priceMode')?String(payload.priceMode).toUpperCase():r.priceMode,p=pricing(m,own(payload,'priceAmount')?payload.priceAmount:r.priceAmount),a=own(payload,'startsAt')?nil(payload.startsAt):r.startsAt,b=own(payload,'endsAt')?nil(payload.endsAt):r.endsAt;await uniqueCode(companyId,r.configId,c,r.id,t);dates(a,b);if(payload.isDefault===true)await db.BundlePromotion.update({isDefault:false},{where:{companyId,configId:r.configId,id:{[Op.ne]:r.id}},transaction:t});const v={code:c,priceMode:m,priceAmount:p,startsAt:a,endsAt:b,updatedBy:userId};['name','description','currencyCode','badgeText','isDefault','sortOrder','isActive'].forEach(f=>{if(own(payload,f))v[f]=['description','badgeText'].includes(f)?nil(payload[f]):f==='sortOrder'?+(payload[f]||0):f==='currencyCode'?String(payload[f]).toUpperCase():payload[f]});await r.update(v,{transaction:t});await t.commit();return getBundleById({companyId,bundleId})}catch(e){if(!t.finished)await t.rollback();throw e}}
async function changeBundleStatus({companyId,bundleId,userId,isActive}){const r=await get(db.BundlePromotion,bundleId,companyId,'Bundle not found.','BUNDLE_PROMOTION_NOT_FOUND');await r.update({isActive,updatedBy:userId});return getBundleById({companyId,bundleId})}
async function deleteBundle({companyId,bundleId}){const t=await db.sequelize.transaction();try{const r=await get(db.BundlePromotion,bundleId,companyId,'Bundle not found.','BUNDLE_PROMOTION_NOT_FOUND',t,true);await db.BundlePromotionItem.destroy({where:{companyId,bundlePromotionId:bundleId},transaction:t});await r.destroy({transaction:t});await t.commit();return{id:bundleId}}catch(e){if(!t.finished)await t.rollback();throw e}}
async function getItemById({companyId,itemId}){const r=await db.BundlePromotionItem.findOne({where:{id:itemId,companyId},include:itemInc});if(!r)throw new AppError('Item not found.',404,'BUNDLE_ITEM_NOT_FOUND');return r}
async function listItems({companyId,bundleId}){await get(db.BundlePromotion,bundleId,companyId,'Bundle not found.','BUNDLE_PROMOTION_NOT_FOUND');return db.BundlePromotionItem.findAll({where:{companyId,bundlePromotionId:bundleId},include:itemInc,order:[['sortOrder','ASC']]})}
async function protectionScheme(companyId,id,t){const r=await db.ProtectionScheme.findOne({where:{id,companyId},transaction:t});if(!r)throw new AppError('Protection scheme not found.',400,'BUNDLE_PROTECTION_SCHEME_INVALID');return r}
async function refs(companyId,payload,current,t){const itemType=own(payload,'itemType')?String(payload.itemType).trim().toUpperCase():(current?.itemType||'PRODUCT');let productId=own(payload,'productId')?nil(payload.productId):(current?.productId||null),productVariantId=own(payload,'productVariantId')?nil(payload.productVariantId):(current?.productVariantId||null),protectionSchemeId=own(payload,'protectionSchemeId')?nil(payload.protectionSchemeId):(current?.protectionSchemeId||null);if(itemType==='PRODUCT'){if(!productId)throw new AppError('PRODUCT items require productId.',400,'BUNDLE_ITEM_PRODUCT_REQUIRED');protectionSchemeId=null;await product(companyId,productId,t);await variant(companyId,productId,productVariantId,t)}else if(itemType==='PROTECTION_PLAN'){if(!protectionSchemeId)throw new AppError('PROTECTION_PLAN items require protectionSchemeId.',400,'BUNDLE_PROTECTION_SCHEME_REQUIRED');productId=null;productVariantId=null;await protectionScheme(companyId,protectionSchemeId,t)}else if(itemType==='TEXT'){productId=null;productVariantId=null;protectionSchemeId=null}else{throw new AppError('Unsupported bundle item type.',400,'BUNDLE_ITEM_TYPE_INVALID')}return{itemType,productId,productVariantId,protectionSchemeId}}
async function createItem({companyId,bundleId,userId,payload}){const t=await db.sequelize.transaction();try{await get(db.BundlePromotion,bundleId,companyId,'Bundle not found.','BUNDLE_PROMOTION_NOT_FOUND',t,true);const x=await refs(companyId,payload,null,t),r=await db.BundlePromotionItem.create({companyId,bundlePromotionId:bundleId,...x,label:String(payload.label).trim(),description:nil(payload.description),quantity:+(payload.quantity||1),isIncluded:payload.isIncluded!==false,sortOrder:+(payload.sortOrder||0),isActive:payload.isActive!==false,createdBy:userId,updatedBy:userId},{transaction:t});await t.commit();return getItemById({companyId,itemId:r.id})}catch(e){if(!t.finished)await t.rollback();throw e}}
async function updateItem({companyId,itemId,userId,payload}){const t=await db.sequelize.transaction();try{const r=await get(db.BundlePromotionItem,itemId,companyId,'Item not found.','BUNDLE_ITEM_NOT_FOUND',t,true),x=await refs(companyId,payload,r,t),v={...x,updatedBy:userId};['label','description','quantity','isIncluded','sortOrder','isActive'].forEach(f=>{if(own(payload,f))v[f]=f==='description'?nil(payload[f]):['quantity','sortOrder'].includes(f)?+payload[f]:payload[f]});await r.update(v,{transaction:t});await t.commit();return getItemById({companyId,itemId})}catch(e){if(!t.finished)await t.rollback();throw e}}
async function changeItemStatus({companyId,itemId,userId,isActive}){const r=await get(db.BundlePromotionItem,itemId,companyId,'Item not found.','BUNDLE_ITEM_NOT_FOUND');await r.update({isActive,updatedBy:userId});return getItemById({companyId,itemId})}
async function deleteItem({companyId,itemId}){const r=await get(db.BundlePromotionItem,itemId,companyId,'Item not found.','BUNDLE_ITEM_NOT_FOUND');await r.destroy();return{id:itemId}}
module.exports={listConfigs,getConfigById,createConfig,updateConfig,changeConfigStatus,deleteConfig,listBundles,getBundleById,createBundle,updateBundle,changeBundleStatus,deleteBundle,listItems,getItemById,createItem,updateItem,changeItemStatus,deleteItem};
